--- tmp/collect.py ---
import json, re, unicodedata
from pathlib import Path
from urllib.parse import unquote, urlsplit
from html import unescape

root = Path(__file__).resolve().parents[1]
pages = {p.name.casefold(): p.read_text(encoding='utf-8') for p in (root/'site').glob('*.html')}
def clean(s):
    return unicodedata.normalize('NFC', unescape(re.sub('<[^>]*>', '', s))).strip().lower()
records, aliases = {}, {}
for filename, source in pages.items():
    redirect = re.search(r'http-equiv="refresh"[^>]*content="[^"]*url=([^";]+)', source, re.I)
    if redirect:
        aliases[filename] = unquote(redirect[1]).casefold()
        continue
    if not re.search(r'<section\b[^>]*id="(?:sinonimos|analogas)"', source):
        continue
    word = clean(re.search(r'<h1>(.*?)</h1>', source, re.S)[1])
    theme = clean(re.search(r'Tema: ([^<]+)', source)[1])
    links = []
    for section in re.findall(r'<section\b[^>]*id="(?:sinonimos|analogas)"[^>]*>(.*?)</section>', source, re.S):
        links += re.findall(r'href="([^"]+)"', section)
    records[filename] = (word, theme, links)
def resolve(href):
    filename = unquote(urlsplit(unescape(href)).path).split('/')[-1].casefold()
    seen = set()
    while filename in aliases and filename not in seen:
        seen.add(filename)
        filename = aliases[filename]
    return records.get(filename)
graph = {v[0]: set() for v in records.values()}
themes = {v[0]: v[1] for v in records.values()}
missing = set()
for word, theme, links in records.values():
    for link in links:
        target = resolve(link)
        if not target:
            missing.add(link)
            continue
        other = target[0]
        if other != word:
            graph[word].add(other)
            graph[other].add(word)
graph = {w: sorted(v) for w,v in sorted(graph.items())}
degree = max(map(len, graph.values()))
leaders = [w for w in graph if len(graph[w]) == degree]
result = {'words': len(graph), 'relations': sum(map(len, graph.values()))//2, 'most_connected': leaders}
(root/'words.json').write_text(json.dumps(graph, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
(root/'result.json').write_text(json.dumps(result, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
(root/'tmp/payload.json').write_text(json.dumps({'graph':graph,'themes':themes,'stats':result},ensure_ascii=False),encoding='utf-8')
print(json.dumps(result,ensure_ascii=False))
print(f'Canonical pages: {len(records)}; redirects: {len(aliases)}; excluded link targets: {len(missing)}; maximum degree: {degree}')
assert all(w in graph[v] for v, neighbors in graph.items() for w in neighbors)
assert all(w not in neighbors for w, neighbors in graph.items())
assert resolve('saudades.html')[0] == 'saudade'
assert 'nostalgia' in graph['saudade']
print('PASS: symmetric adjacency, no self-links, aliases resolved, saudade linked to nostalgia')


